#!/usr/bin/env python3
"""Jeu d'icônes Sylva (style « médaillon » Feu de camp).

Chaque icône : grille 24 x 24, trait 1,7 arrondi (hérité du <svg class="ic">).
  f : formes pleines, en couleur du trait avec une opacité (« ombre de braise »)
  l : tracés au trait
Lancer `python3 tools/icons.py` réécrit le sprite entre les marqueurs
<!--ICONS--> et <!--/ICONS--> de index.html. Dans le code : ic("feu").
"""
import math, re, os

def trefoil():
    p = []
    for a in (90, 210, 330):
        a1, a2 = math.radians(a - 30), math.radians(a + 30)
        r1, r2 = 3.2, 8.6
        P = lambda r, t: "%.2f %.2f" % (12 + r * math.cos(t), 12 - r * math.sin(t))
        p.append("M%s L%s A%s %s 0 0 0 %s L%s A%s %s 0 0 1 %s Z" % (P(r1, a1), P(r2, a1), r2, r2, P(r2, a2), P(r1, a2), r1, r1, P(r1, a1)))
    return " ".join(p)

