ALIAS = {"blesse": "secours", "soigner": "secours", "toxique": "alerte", "nord": "orientation", "sang": "eau", "tente": "bivouac", "resto": "manger", "sante": "secours"}

def symbol(name, f, lines):
    out = '<symbol id="i-%s" viewBox="0 0 24 24">' % name
    if f:
        out += '<path d="%s" fill="currentColor" stroke="none" style="fill-opacity:var(--icf,.38)"/>' % f
    for d in lines:
        out += '<path d="%s"/>' % d
    return out + "</symbol>"

def sprite():
    s = ['<svg xmlns="http://www.w3.org/2000/svg" style="position:absolute;width:0;height:0;overflow:hidden" aria-hidden="true">']
    s.append('<defs>')
    for n, (f, l) in I.items():
        s.append(symbol(n, f, l))
    for a, n in ALIAS.items():
        f, l = I[n]
        s.append(symbol(a, f, l))
    s.append('</defs></svg>')
    return "".join(s)

if __name__ == "__main__":
    root = os.path.join(os.path.dirname(__file__), "..")
    p = os.path.join(root, "index.html")
    h = open(p, encoding="utf-8").read()
    block = "<!--ICONS-->" + sprite() + "<!--/ICONS-->"
    if "<!--ICONS-->" in h:
        h = re.sub(r"<!--ICONS-->.*?<!--/ICONS-->", lambda m: block, h, flags=re.S)
    else:
        h = h.replace("<body>", "<body>\n" + block, 1)
    open(p, "w", encoding="utf-8").write(h)
    print(len(I) + len(ALIAS), "icônes")
